create policy "Public can read published subjects" on public.subjects for select to anon using (published = true);
create policy "Public can read chapters in published subjects" on public.chapters for select to anon using (exists (select 1 from public.subjects s where s.id=subject_id and s.published=true));
create policy "Public can read published lectures" on public.lectures for select to anon using (published=true and exists (select 1 from public.chapters c join public.subjects s on s.id=c.subject_id where c.id=chapter_id and s.published=true));
create policy "Public can read published tests" on public.tests for select to anon using (published=true and exists (select 1 from public.lectures l join public.chapters c on c.id=l.chapter_id join public.subjects s on s.id=c.subject_id where l.id=lecture_id and l.published=true and s.published=true));
create policy "Public can read published lecture notes" on storage.objects for select to anon using (bucket_id='lecture-notes' and exists (select 1 from public.lectures l join public.chapters c on c.id=l.chapter_id join public.subjects s on s.id=c.subject_id where l.id::text=(storage.foldername(name))[1] and l.published=true and s.published=true));